const now = new Date();
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const timePattern = /^([01]\d|2[0-3]):[0-5]\d$/;

function zonedParts(date, timeZone) {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  });
  return Object.fromEntries(formatter.formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
}

const due = [];
for (const item of $input.all()) {
  const user = item.json || {};
  const userId = String(user.user_id || '').trim();
  const email = String(user.email || '').trim();
  const sendTime = String(user.send_time || '').trim();
  const timeZone = String(user.timezone || '').trim();
  const consent = String(user.consent_at || '').trim();
  if (!userId || !emailPattern.test(email) || !timePattern.test(sendTime) || !timeZone || !consent) continue;

  let local;
  try {
    local = zonedParts(now, timeZone);
  } catch {
    continue;
  }
  const localTime = `${local.hour}:${local.minute}`;
  const localDate = `${local.year}-${local.month}-${local.day}`;
  if (localTime !== sendTime) continue;

  const lastSentRaw = String(user.last_newsletter_sent_at || '').trim();
  if (lastSentRaw) {
    const lastSent = new Date(lastSentRaw);
    if (Number.isFinite(lastSent.getTime())) {
      const sentLocal = zonedParts(lastSent, timeZone);
      const sentLocalDate = `${sentLocal.year}-${sentLocal.month}-${sentLocal.day}`;
      if (sentLocalDate === localDate) continue;
    }
  }

  due.push({ json: { user_id: userId, delivery_mode: 'scheduled', scheduled_local_date: localDate } });
}

return due;

const result = $json || {};
if (result.status) return { json: result };
let userId = String(result.user_id || '').trim();
if (!userId) {
  try { userId = String($('Select Due Users').item.json.user_id || '').trim(); } catch {}
}
return { json: {
  status: 'failed',
  user_id: userId,
  article_count: 0,
  message: 'Newsletter delivery failed temporarily. Please try again later.'
} };
